def preserves(n, R, S, f):
    return all(not (R >> (n*x+y) & 1) or (S >> (n*f[x]+f[y]) & 1)
               for x in range(n) for y in range(n))

def inverse(p):
    q=[0]*len(p)
    for i,j in enumerate(p): q[j]=i
    return tuple(q)

